// ── Parse & Validate Orchestrator Response ──
const httpResponse = $input.first().json;

let rawContent = '';
try {
  rawContent = httpResponse.choices[0].message.content;
} catch (e) {
  throw new Error('Invalid LM Studio response format: missing choices[0].message.content');
}

let cleaned = rawContent.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Failed to parse orchestrator JSON: ${e.message}\nRaw: ${rawContent.substring(0, 500)}`);
}

const requiredFields = ['goal', 'tasks', 'approval_required', 'confidence'];
const missing = requiredFields.filter(f => !(f in parsed));
if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

if (!Array.isArray(parsed.tasks)) {
  throw new Error('"tasks" must be an array');
}
if (parsed.tasks.length === 0) {
  throw new Error('"tasks" array is empty — at least one task is required');
}

const validAgents = ['research_agent', 'writer_agent', 'code_agent', 'data_agent', 'dataviz_agent', 'td_agent', 'critique_agent', 'qa_agent'];
for (let i = 0; i < parsed.tasks.length; i++) {
  const task = parsed.tasks[i];
  if (!task.agent || !validAgents.includes(task.agent)) {
    throw new Error(`Task ${i}: invalid or missing agent "${task.agent}". Must be one of: ${validAgents.join(', ')}`);
  }
  if (!task.task || typeof task.task !== 'string') {
    throw new Error(`Task ${i}: missing or invalid "task" description`);
  }
  if (!Array.isArray(task.depends_on)) task.depends_on = [];
  if (!Array.isArray(task.parallel_with)) task.parallel_with = [];
}

if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 100) {
  throw new Error('"confidence" must be a number between 0 and 100');
}

const threshold = $input.first().json.body?.confidence_threshold ?? 50;
if (parsed.confidence < threshold) {
  throw new Error(`Confidence (${parsed.confidence}) is below threshold (${threshold}). Refusing to proceed.`);
}

const enriched = {
  ...parsed,
  session_id: $input.first().json.body?.session_id || ('canvas-' + Date.now()),
  mode: $input.first().json.body?.mode || 'collaborative',
  status: 'awaiting_approval',
  created_at: new Date().toISOString(),
  orchestrator_model: 'penai/gpt-oss-20b'
};

return [{ json: enriched }];

const fs = require('fs');
const path = require('path');

const sessionData = $input.first().json;
const dir = '/canvas-state';
const filePath = path.join(dir, `${sessionData.session_id}.json`);

// Create directory if it doesn't exist
if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
}

// Append-only — never overwrite existing session
if (!fs.existsSync(filePath)) {
  fs.writeFileSync(filePath, JSON.stringify(sessionData, null, 2), 'utf8');
}

return [{ json: { ...sessionData, state_written: true, file_path: filePath } }];

// ── Process Resume Payload ──
// The Wait node resumes with the webhook body as input
const resumeData = $input.first().json.body || $input.first().json;

const decision = (resumeData.decision || '').toLowerCase();
const sessionId = resumeData.session_id;

if (!sessionId) {
  throw new Error('Resume payload missing session_id');
}

const validDecisions = ['approve', 'modify', 'reject'];
if (!validDecisions.includes(decision)) {
  throw new Error(`Invalid decision "${decision}". Must be one of: ${validDecisions.join(', ')}`);
}

// Re-read the session state file from disk to get the latest task plan
// The Read Session State node will handle this — we just pass forward
return [{
  json: {
    session_id: sessionId,
    decision: decision,
    filePath: `/canvas-state/${sessionId}.json`
  }
}];

const fs = require('fs');

const decision = $('Parse Resume').first().json.decision;
const sessionId = $('Parse Resume').first().json.session_id;
const filePath = `/canvas-state/${sessionId}.json`;

if (!fs.existsSync(filePath)) {
  throw new Error(`Session file not found: ${filePath}`);
}

const raw = fs.readFileSync(filePath, 'utf8');
const sessionState = JSON.parse(raw);

let updatedState = { ...sessionState, decision, decided_at: new Date().toISOString() };

switch (decision) {
  case 'approve':
    updatedState.status = 'running';
    updatedState.approved_at = new Date().toISOString();
    break;
  case 'reject':
    updatedState.status = 'rejected';
    updatedState.rejected_at = new Date().toISOString();
    break;
  case 'modify':
    updatedState.status = 'modification_requested';
    updatedState.modified_at = new Date().toISOString();
    break;
}

return [{
  json: {
    session_id: sessionId,
    decision: decision,
    goal: sessionState.goal,
    tasks: sessionState.tasks,
    updatedState: updatedState
  }
}];

const fs = require('fs');
const path = require('path');

const data = $input.first().json;
const dir = '/canvas-state';
const filePath = path.join(dir, `${data.updatedState.session_id}.json`);

// Create directory if it doesn't exist
if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
}

fs.writeFileSync(filePath, JSON.stringify(data.updatedState, null, 2), 'utf8');

return [{ json: { ...data, state_updated: true, file_path: filePath } }];
